#!/usr/bin/env python3
import sys
sys.path.append('/home/ctfplayer/ctf_files')
from almostxor import to_num, get_nums, get_vals, get_chrs

def decrypt_vals(c_chr, k_chr, n):
    # Inverse of encr_vals function
    # encr_vals: return (m_chr + k_chr) & ((1 << n) - 1)
    # So decrypt_vals: return (c_chr - k_chr) & ((1 << n) - 1)
    mask = (1 << n) - 1
    return (c_chr - k_chr) & mask

def decrypt(k, c, n):
    if (n >= 8): 
        raise ValueError("n is too high!")

    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]  # repeated key
    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]

    c_vals, k_vals, m_vals = [], [], []
    for lst in c_val_list: 
        c_vals += lst
    for lst in k_val_list: 
        k_vals += lst

    m_vals = [decrypt_vals(c_vals[i], k_vals[i % len(k_vals)], n)
            for i in range(0, len(c_vals))]

    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in m_val_list])

if __name__ == "__main__":
    # Read ciphertext
    with open('/home/ctfplayer/ctf_files/ciphertext', 'r') as f:
        ciphertext_hex = f.read().strip().replace('\n', '')

    # Convert hex to bytes
    import binascii
    cipher_bytes = binascii.unhexlify(ciphertext_hex)
    ciphertext = cipher_bytes.decode('latin1')  # Use latin1 to handle any byte values

    print(f"Ciphertext length: {len(ciphertext)} bytes")

    # Try different n values and keys
    # Since we know the flag format is flag{...}, we can check for that
    import string

    # Define a function to check if a string contains a valid flag
    def contains_flag(text):
        flag_start = text.find("flag{")
        if flag_start == -1:
            return False, ""
        flag_end = text.find("}", flag_start)
        if flag_end == -1:
            return False, ""
        return True, text[flag_start:flag_end+1]

    # Define a function to check if a string is mostly printable
    def is_mostly_printable(text, threshold=0.7):
        printable_count = sum(1 for c in text if c in string.printable)
        return printable_count / len(text) >= threshold

    # Common keys to try
    common_keys = [
        "key", "flag", "ctf", "CTF", "crypto", "cipher", "xor", "add", "a", "b", "c", "k", "KEY"
    ]

    # Try all values of n from 1 to 7 (since n < 8)
    for n in range(1, 8):
        print(f"\n== Testing with n = {n} ==")

        # Try common keys
        for key in common_keys:
            try:
                decrypted = decrypt(key, ciphertext, n)

                # Check if result contains flag or is mostly printable
                has_flag, flag = contains_flag(decrypted)
                if has_flag:
                    print(f"Found flag with n={n}, key='{key}': {flag}")
                    print(f"Full decrypted text: {decrypted}")
                elif is_mostly_printable(decrypted):
                    print(f"Mostly printable result with n={n}, key='{key}': {decrypted[:50]}...")
            except Exception as e:
                # Just skip errors
                pass

        # Try brute-forcing keys that start with common patterns
        for prefix in ['f', 'fl', 'fla', 'flag', 'c', 'ct', 'ctf', 'k', 'ke', 'key']:
            for c in string.ascii_lowercase + string.digits:
                key = prefix + c
                try:
                    decrypted = decrypt(key, ciphertext, n)
                    has_flag, flag = contains_flag(decrypted)
                    if has_flag:
                        print(f"Found flag with n={n}, key='{key}': {flag}")
                        print(f"Full decrypted text: {decrypted}")
                except Exception as e:
                    pass

# Try brute forcing for n=5, which is likely based on constraints
print("\n== Detailed search with n=5 ==")
for a in string.ascii_lowercase + string.digits:
    for b in string.ascii_lowercase + string.digits:
        for c in string.ascii_lowercase + string.digits:
            key = a + b + c
            try:
                decrypted = decrypt(key, ciphertext, 5)
                has_flag, flag = contains_flag(decrypted)
                if has_flag:
                    print(f"Found flag with n=5, key='{key}': {flag}")
                    print(f"Full decrypted text: {decrypted}")
                elif is_mostly_printable(decrypted, 0.8):
                    print(f"Very readable result with n=5, key='{key}': {decrypted[:50]}...")
            except Exception as e:
                pass

