import sys
import string
from itertools import product

sys.path.append('/home/ctfplayer/ctf_files')
from almostxor import to_num, get_nums, get_vals, get_chrs, encr_vals

# We need to define a decryption function to reverse the encryption
def decr_vals(c_val, k_val, n):
    mask = (1 << n) - 1
    # To reverse (c_val = (m_val + k_val) & mask), we do: m_val = (c_val - k_val) & mask
    # Need to handle underflow for modular arithmetic
    return (c_val - k_val) & mask

# Decrypt function to reverse the encrypt function
def decrypt(k, c, n):
    if (n >= 8): 
        raise ValueError("n is too high!")

    # Split ciphertext into n-bit values
    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]

    # Generate key values similar to encryption
    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]  # repeated key
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]

    # Flatten lists
    c_vals, k_vals, m_vals = [], [], []
    for lst in c_val_list: c_vals += lst
    for lst in k_val_list: k_vals += lst

    # Decrypt each value
    m_vals = [decr_vals(c_vals[i], k_vals[i % len(k_vals)], n) 
              for i in range(0, len(c_vals))]

    # Group values back into chunks of 8
    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]

    # Convert back to characters
    return "".join([get_chrs(lst, n) for lst in m_val_list])

