    c_vals = [encr_vals(m_vals[i], k_vals[i % len(k_vals)], n)
        for i in range(0, len(m_vals))]
    c_val_list = [c_vals[i:i+8] for i in range(0, len(c_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in c_val_list])

