    # Check if the text contains a high percentage of printable ASCII characters
    printable_count = sum(1 for c in text if c in string.printable)
    if printable_count / len(text) < 0.7:
        return False

    # Check for common English words
    common_words = ['the', 'be', 'to', 'of', 'and', 'in', 'that', 'have', 'flag']
    word_count = sum(1 for word in common_words if word in text.lower())
    if word_count == 0:
        return False

    return True

