    n = 7
    print(f"\n=== Brute forcing with n = {n} ===")

    for key_len in range(1, 7):  # Try keys of length 1-6
        for key_char in "abcdefghijklmnopqrstuvwxyz":
            key = key_char * key_len
            try:
