                    print(f"Key: '{key}', n: {n}")
                    print(f"Full decrypted: {decrypted}")
                    return

                if "flag" in decrypted.lower():
                    print(f"Potential match with key='{key}', n={n}:")
                    print(decrypted)
            except Exception as e:
                pass

