#!/usr/bin/env python3
import string

# Original functions from almostxor.py
def to_num(s):
    x = 0
    for i in range(len(s)): 
        x += ord(s[-1-i]) * pow(256, i)
    return x

def get_nums(s, n):
    sections = [s[i:i+n] for i in range(0, len(s), n)]
    if len(sections[-1]) < n:
        sections[-1] = sections[-1] + ("\x00" * (n - len(sections[-1])))
    return [to_num(x) for x in sections]

def get_vals(x, n):
    vals = []
    mask = (1 << n) - 1
    for i in range(8):
        vals.append(x & mask)
        x = x >> n
    vals.reverse()
    return vals

def get_chrs(val_list, n):
    if not val_list:
        return ""
    x = val_list[0]
    chrs = []
    for i in range(1, len(val_list)):
        x <<= n
        x += val_list[i]
    for i in range(n):
        chrs.append(chr(x % 256))
        x //= 256
    chrs.reverse()
    return "".join(chrs)

def encr_vals(m_chr, k_chr, n):
    return (m_chr + k_chr) & ((1 << n) - 1)

def decr_vals(c_chr, k_chr, n):
    mask = (1 << n) - 1
    return (c_chr - k_chr) & mask

def decrypt(k, c, n):
    if (n >= 8): 
        raise ValueError("n is too high!")

    rep_k = k * (len(c) // len(k)) + k[:len(c) % len(k)]  # repeated key

    c_val_list = [get_vals(x, n) for x in get_nums(c, n)]
    k_val_list = [get_vals(x, n) for x in get_nums(rep_k, n)]

    c_vals, k_vals, m_vals = [], [], []
    for lst in c_val_list: 
        c_vals += lst
    for lst in k_val_list: 
        k_vals += lst

    m_vals = [decr_vals(c_vals[i], k_vals[i % len(k_vals)], n)
            for i in range(0, len(c_vals))]

    m_val_list = [m_vals[i:i+8] for i in range(0, len(m_vals), 8)]
    return "".join([get_chrs(lst, n) for lst in m_val_list])

